# Generated by Descant: acceptance tests.

RSpec.describe Timekeeping::LocalOwner do
  # "It counts only when `Timekeeping::EntryOwner.for` returns `:prepared` and `handoff_step` is nil."
  # The generation number itself does not move here: only the handoff step is set, so a check that
  # compares numbers alone, or replays before the fence, lets these requests through.
  it "a prepare at the current generation while a handoff step is set answers stale_generation, even as a replay of a stored operation" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    project = create(:project, client: create(:client, company:))
    new_entry = lambda do
      Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                      work_date: Date.new(2026, 3, 2), duration: 60.0, bill_status: "unbilled").id
    end
    first_entry = new_entry.call
    second_entry = new_entry.call
    actor = described_class::Actor.service(name: "invoice-boundary", company_id: company.id,
                                           operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS)
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    prepare = lambda do |operation_id, invoice_id, entries|
      described_class.call(
        operation: :prepare, company_id: company.id, generation: generation.to_s, actor:,
        params: { "body" => { "invoice_id" => invoice_id, "operation_id" => operation_id, "disposition" => "active",
                              "entries" => entries, "generation" => generation } }
      )
    end
    stored_operation = SecureRandom.uuid

    expect(prepare.call(stored_operation, 501, [first_entry]).status).to eq(200)
    TimekeepingOwnership.current.update!(handoff_step: "freeze")
    before = %w[reservations invoice_operations entry_audits entry_outbox_items].index_with { |table| count.call(table) }

    replay = prepare.call(stored_operation, 501, [first_entry])
    fresh = prepare.call(SecureRandom.uuid, 502, [second_entry])

    expect([replay.status, replay.body.with_indifferent_access[:reason]]).to eq([409, "stale_generation"])
    expect([fresh.status, fresh.body.with_indifferent_access[:reason]]).to eq([409, "stale_generation"])
    expect(%w[reservations invoice_operations entry_audits entry_outbox_items].index_with { |table| count.call(table) })
      .to eq(before)
  end

  # The entry path checks the generation through the same shared steps the reservation writers use, so
  # a malformed or wrong generation is refused there too while the monolith is the prepared owner.
  it "an entry create with a malformed or wrong generation answers stale_generation while ownership is prepared" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    actor = described_class::Actor.user(user_id: user.id, role: "owner")
    body = { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 10.0, "note" => "fenced",
             "source" => TimesheetEntry::SOURCES.first, "source_metadata" => {} }
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    before = %w[entries entry_audits idempotency_records entry_outbox_items].index_with { |table| count.call(table) }

    [nil, "", "abc", "#{generation}.0", " #{generation}", (generation + 1).to_s, (generation - 1).to_s]
      .each_with_index do |sent_generation, index|
        outcome = described_class.call(operation: :create, company_id: company.id, generation: sent_generation, actor:,
                                       params: { "idempotency_key" => "entry-fence-#{index}", "body" => body })

        expect([sent_generation, outcome.status, outcome.body.with_indifferent_access[:reason].to_s])
          .to eq([sent_generation, 409, "stale_generation"])
      end
    expect(%w[entries entry_audits idempotency_records entry_outbox_items].index_with { |table| count.call(table) })
      .to eq(before)
  end
end
